WITH parsed AS (SELECT id, effective_from, ARRAY_MIN(tier_prices) AS lowest_price, ELEMENT_AT(tier_prices, 1) AS entry_price, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers WHERE YEAR(effective_from) >= 2023) SELECT *, AVG(avg_tier_price) OVER (ORDER BY effective_from ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS avg_tier_price_avg_6, SUM(entry_price) OVER (ORDER BY lowest_price ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_entry_price, LAG(avg_tier_price, 1) OVER (ORDER BY entry_price ASC, id ASC) AS prev_avg_tier_price FROM parsed
